<?php
declare(strict_types=1);require_once __DIR__.'/../config/agency_auth.php';require_once __DIR__.'/../config/throttle.php';agency_session();if(agency_user()){header('Location: /nexustraveltech/acente/');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';$key=throttle_key('agency',(string)$email);$status=throttle_check($key);if(!$status['allowed']){$error='Çok fazla hatalı deneme. '.ceil($status['retry_after']/60).' dakika sonra tekrar deneyin.';}else{$q=db()->prepare("SELECT u.id,u.agency_id,u.full_name,u.email,u.password_hash,u.role,a.company_name FROM agency_users u JOIN agencies a ON a.id=u.agency_id WHERE u.email=? AND a.status='active' LIMIT 1");$q->execute([$email]);$u=$q->fetch();if($u&&password_verify($password,$u['password_hash'])){throttle_reset($key);session_regenerate_id(true);unset($u['password_hash']);$_SESSION['agency_user']=$u;db()->prepare('UPDATE agency_users SET last_login_at=now() WHERE id=?')->execute([$u['id']]);header('Location: /nexustraveltech/acente/');exit;}throttle_hit($key);$statusQ=db()->prepare('SELECT a.status,a.verified_at FROM agencies a JOIN agency_users u ON u.agency_id=a.id WHERE u.email=? LIMIT 1');$statusQ->execute([$email]);$agencyRow=$statusQ->fetch();if($agencyRow&&$agencyRow['status']==='pending'){$error=$agencyRow['verified_at']?'Hesabınız e-postanız doğrulandı; yönetici onayı bekleniyor.':'E-postanızı doğrulamadınız. Kayıt sonrası gönderilen bağlantıyı kullanın.';}else{$error='E-posta, şifre veya acente durumu hatalı.';}}}?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NEXUS Acenta</title><style>body{min-height:100vh;margin:0;display:grid;place-items:center;font-family:Arial;background:#10211f}.c{background:#fff;width:min(400px,calc(100% - 30px));padding:30px}.c input,.c button{width:100%;box-sizing:border-box;padding:12px;margin:7px 0}.c button{background:#d7ff48;border:0;font-weight:bold}.e{color:#c33}</style></head><body><form method="post" class="c"><h1>NEXUS Acenta</h1><p>Canlı ürün, teklif ve rezervasyon merkezi.</p><?php if($error):?><p class="e"><?=htmlspecialchars($error)?></p><?php endif;?><input type="email" name="email" placeholder="İş e-postası" required><input type="password" name="password" placeholder="Şifre" required><button>Giriş yap</button><p><a href="/nexustraveltech/acente/kayit" style="color:#0d7a4a">Hesabınız yok mu? Kayıt ol →</a></p></form></body></html>
